// On-device item screenshot recognition. Images and OCR output stay in memory.
const ITEM_OCR_CDN='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';
let itemOcrScriptPromise=null,itemOcrImage=null,itemOcrObjectUrl='',itemOcrBusy=false,itemOcrTransition=false;
function openItemImport(position){
 const options=[...slots,...extra].map(([k,n])=>[k,n]);
 const fields=`<div class="item-ocr-intro full"><strong>Adicionar equipamento por imagem</strong><p>Cola uma captura de ecrã (Ctrl+V) ou escolhe um ficheiro. O reconhecimento é feito neste navegador. Revê tudo no editor antes de guardar.</p></div><div id="itemOcrDrop" class="item-ocr-drop full" tabindex="0" role="button" aria-label="Colar ou escolher uma imagem"><span class="item-ocr-drop-icon">▧</span><strong>Cola a imagem aqui</strong><small>ou escolhe um ficheiro PNG, JPG ou WebP</small><input id="itemOcrFile" type="file" accept="image/png,image/jpeg,image/webp"></div><div id="itemOcrPreviewWrap" class="item-ocr-preview full" hidden><img id="itemOcrPreview" alt="Pré-visualização da captura"><button type="button" id="itemOcrClear">Remover imagem</button></div><div id="itemOcrStatus" class="item-ocr-status full" role="status">O OCR corre localmente no teu browser. A primeira utilização descarrega o motor gratuito.</div><div class="item-ocr-actions full"><button type="button" id="itemOcrRun" disabled>Reconhecer texto</button></div>${selectPairs('inventorySlot','Tipo de equipamento','weapon',options)}${field('inventoryName','Nome detetado / nome do item','')}${selectPairs('inventoryUpgrade','Melhoramento','',[['','Detetar automaticamente'],...Array.from({length:16},(_,i)=>['+'+i,'+'+i])])}${field('ocrText','Texto reconhecido · corrige se necessário','','textarea')}<p class="hint full">O nome, melhoramento e bónus são apenas sugestões. A imagem não é guardada no perfil nem enviada para um servidor.</p>`;
 open('Adicionar ao inventário',fields,v=>{
   const slot=options.some(([k])=>k===v.inventorySlot)?v.inventorySlot:'weapon';
   const proposal=parseItemScreenshot(v.ocrText,slot,v.inventoryName,v.inventoryUpgrade);$('#form').dataset.itemOcr='false';$('#form').dataset.itemOcrReview='true';itemOcrTransition=true;
   queueMicrotask(()=>{editSlot(slot,{inventory:true,position});fillItemEditor(proposal);});
 });
 const form=$('#form'),saveButton=form.querySelector('[type="submit"]');form.dataset.itemOcr='true';saveButton.textContent='Rever no editor';
 $('#itemOcrFile').addEventListener('change',e=>useItemOcrImage(e.target.files?.[0]));
 $('#itemOcrClear').addEventListener('click',clearItemOcrImage);
 $('#itemOcrRun').addEventListener('click',recognizeItemScreenshot);
}
function clearItemOcrImage(){if(itemOcrObjectUrl)URL.revokeObjectURL(itemOcrObjectUrl);itemOcrObjectUrl='';itemOcrImage=null;const w=$('#itemOcrPreviewWrap');if(w)w.hidden=true;const run=$('#itemOcrRun');if(run)run.disabled=true;}
function useItemOcrImage(file){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){setItemOcrStatus('Escolhe uma imagem PNG, JPG ou WebP.');return;}if(file.size>12*1024*1024){setItemOcrStatus('A imagem excede o limite de 12 MB. Recorta a captura e tenta novamente.');return;}clearItemOcrImage();itemOcrImage=file;itemOcrObjectUrl=URL.createObjectURL(file);$('#itemOcrPreview').src=itemOcrObjectUrl;$('#itemOcrPreviewWrap').hidden=false;$('#itemOcrRun').disabled=false;setItemOcrStatus('Imagem pronta. Seleciona “Reconhecer texto” para extrair os atributos.');}
function setItemOcrStatus(message){const box=$('#itemOcrStatus');if(box)box.textContent=message;}
function loadItemOcr(){if(window.Tesseract)return Promise.resolve(window.Tesseract);if(itemOcrScriptPromise)return itemOcrScriptPromise;itemOcrScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=ITEM_OCR_CDN;script.async=true;script.onload=()=>window.Tesseract?resolve(window.Tesseract):reject(Error('O motor OCR não iniciou.'));script.onerror=()=>reject(Error('Não foi possível carregar o motor OCR. Verifica a ligação à Internet e tenta novamente.'));document.head.append(script);}).catch(error=>{itemOcrScriptPromise=null;throw error;});return itemOcrScriptPromise;}
async function recognizeItemScreenshot(){if(!itemOcrImage||itemOcrBusy)return;itemOcrBusy=true;const button=$('#itemOcrRun');button.disabled=true;let worker;try{setItemOcrStatus('A preparar o reconhecimento…');const T=await loadItemOcr();worker=await T.createWorker('por+eng',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/worker.min.js',langPath:'https://tessdata.projectnaptha.com/4.0.0',logger:m=>{if(m.status==='recognizing text')setItemOcrStatus('A ler o texto… '+Math.round((m.progress||0)*100)+'%');}});const image=await prepareOcrImage(itemOcrImage);const result=await worker.recognize(image);const text=result.data.text.trim();$('#form [name="ocrText"]').value=text;const parsed=parseItemScreenshot(text,$('#form [name="inventorySlot"]').value);if(parsed.slot){$('#form [name="inventorySlot"]').value=parsed.slot;$('#form [name="inventorySlot"]').dispatchEvent(new Event('change',{bubbles:true}));}if(parsed.name)$('#form [name="inventoryName"]').value=parsed.name;if(parsed.upgrade)$('#form [name="inventoryUpgrade"]').value=parsed.upgrade;setItemOcrStatus(text?'Texto reconhecido. Confirma tipo, nome, melhoramento e corrige o texto antes de avançar.':'Não foi possível ler texto nesta imagem. Podes preencher o texto manualmente e continuar.');}catch(error){setItemOcrStatus(error.message||'Falhou o reconhecimento. Podes continuar com os campos manuais.');}finally{if(worker)await worker.terminate().catch(()=>{});itemOcrBusy=false;if(button)button.disabled=!itemOcrImage;}}
function prepareOcrImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);const scale=Math.min(3,1800/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),d=pixels.data;for(let i=0;i<d.length;i+=4){const grey=(d[i]*0.299+d[i+1]*0.587+d[i+2]*0.114);const high=Math.max(0,Math.min(255,(grey-110)*1.22+110));d[i]=d[i+1]=d[i+2]=high;}ctx.putImageData(pixels,0,0);resolve(canvas);};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Não foi possível abrir a imagem.'));};img.src=url;});}
function parseItemScreenshot(text,requestedSlot='weapon',manualName='',manualUpgrade=''){
 const lines=String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),first=lines.slice(0,4).find(x=>/\+\s*\d+\s*$/.test(x))||lines[0]||'';
 const title=String(manualName||first).replace(/\s*\+\s*\d+\s*$/,'').trim();const upgrade=String(manualUpgrade||first.match(/\+\s*(\d+)\s*$/)?.[1]&&('+'+first.match(/\+\s*(\d+)\s*$/)[1])||'+0');
 const all=Object.entries(catalogue()),needle=normalized(title).replace(/[^a-z0-9]/g,''),matches=all.filter(([,e])=>e.slot===requestedSlot&&needle&&normalized(e.label).replace(/[^a-z0-9]/g,'')===needle);let slot=requestedSlot,catalogId=matches[0]?.[0]||'';
 if(!catalogId&&needle){const found=all.find(([,e])=>{const n=normalized(e.label).replace(/[^a-z0-9]/g,'');return n&&needle.length>5&&(needle.includes(n)||n.includes(needle));});if(found){catalogId=found[0];slot=found[1].slot;}}
 const itemName=title||matches[0]?.[1].label||'Item personalizado',entry=catalogue()[catalogId],fixed=entry?.upgrades?.[String(Number(upgrade.replace('+','')))]||'',fixedLabels=new Set(String(fixed).split('\n').map(ocrCanonicalLabel));
 const bonusLines=[],rareLines=[],unmatched=[];let pastTitle=false;
 for(const line of lines){if(!pastTitle){if(line===first)pastTitle=true;continue;}if(/^(equip[aá]vel|pode adicionar|n[ií]vel m[ií]nimo|requer|guerreiro|ninja|sura|xam[aã]|lycan|shaman|shaman|classe|\[)/i.test(line))continue;
   if(fixedLabels.has(ocrCanonicalLabel(line)))continue;
   const parsed=parseRoll(line,bonusOptions(slot,'normal'));if(parsed.type&&parsed.type!=='__custom'){bonusLines.push(line);continue;}const rare=parseRoll(line,bonusOptions(slot,'rare'));if(rare.type&&rare.type!=='__custom'){rareLines.push(line);continue;}if(/\d/.test(line))unmatched.push(line);
 }
 return {slot,catalogId,name:entry?.label||itemName,upgrade,bonuses:bonusLines.slice(0,5).join('\n'),bonus6:rareLines[0]||'',bonus7:rareLines[1]||'',notes:unmatched.join('\n'),raw:String(text||''),overflow:bonusLines.slice(5).concat(rareLines.slice(2),unmatched)};
}
function ocrCanonicalLabel(line){let label=String(line||'').replace(/^\s*[+-]?\d+(?:[.,]\d+)?%?\s+/,'').replace(/\s*:?\s*[+-]?\d+(?:[.,]\d+)?\s*%?\s*$/,'').trim(),key=canonicalBonus(label);if(/^rap\.?\s*(?:de\s*)?feitico$/.test(key))return 'rapidezdefeitico';if(/^res\.?\s*(?:ao|a)\s+vento$/.test(key))return 'resistenciavento';return key.replace(/[^a-z0-9]/g,'');}
function fillItemEditor(proposal){$('#form [type="submit"]').textContent='Guardar';if(itemOcrObjectUrl){const preview=document.createElement('div');preview.id='itemOcrEditorPreview';preview.className='item-ocr-editor-preview full';preview.innerHTML='<img src="'+itemOcrObjectUrl+'" alt="Captura analisada"><div><strong>Proposta lida da imagem</strong><p>Confirma os bónus, o melhoramento e os atributos fixos no editor. A captura será descartada ao fechar.</p></div>';$('#fields').prepend(preview);}const setField=(name,value,fire=false)=>{const el=$('#form [name="'+name+'"]');if(!el||value===undefined||value===null)return;el.value=value;if(fire)el.dispatchEvent(new Event('change',{bubbles:true}));};setField('catalogId',proposal.catalogId||'__custom',true);setField('name',proposal.name);setField('upgrade',proposal.upgrade);setField('notes',[proposal.notes,proposal.overflow.length?'Linhas OCR por rever:\n'+proposal.overflow.join('\n'):''].filter(Boolean).join('\n\n'));const setGroup=(key,count,text,group)=>{const source=String(text||'').split('\n').filter(Boolean);for(let i=0;i<count;i++){const row=$('#form [data-roll="'+key+i+'"]');if(!row||!source[i])continue;const parsed=parseRoll(source[i],bonusOptions(proposal.slot,group));const type=row.querySelector('[name="'+key+i+'_type"]'),val=row.querySelector('[name="'+key+i+'_value"]'),custom=row.querySelector('[name="'+key+i+'_custom"]');type.value=parsed.type||'__custom';type.dispatchEvent(new Event('change',{bubbles:true}));if(parsed.type&&parsed.type!=='__custom'){val.value=parsed.value||'__custom';custom.value=parsed.custom||'';}else custom.value=source[i];}};setGroup('normal',5,proposal.bonuses,'normal');setGroup('rare6',1,proposal.bonus6,'rare');setGroup('rare7',1,proposal.bonus7,'rare');if(proposal.overflow.length)setItemOcrStatus('Algumas linhas OCR ficaram nas Notas para não perder informação. Revê-as antes de guardar.');}
document.addEventListener('paste',e=>{if($('#form')?.dataset.itemOcr!=='true')return;const file=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'))?.getAsFile();if(file){e.preventDefault();useItemOcrImage(file);}});
document.addEventListener('dragover',e=>{if($('#form')?.dataset.itemOcr==='true'&&e.dataTransfer?.types?.includes('Files'))e.preventDefault();});
document.addEventListener('drop',e=>{if($('#form')?.dataset.itemOcr!=='true')return;const file=[...(e.dataTransfer?.files||[])].find(x=>x.type.startsWith('image/'));if(file){e.preventDefault();useItemOcrImage(file);}});
document.addEventListener('click',e=>{if(e.target.id!=='itemOcrFile'&&e.target.closest('#itemOcrDrop'))$('#itemOcrFile').click();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.id==='itemOcrDrop'){e.preventDefault();$('#itemOcrFile').click();}});
document.querySelector('#modal')?.addEventListener('close',()=>{if(itemOcrTransition){itemOcrTransition=false;return;}const form=document.querySelector('#form');if(form.dataset.itemOcr==='true'){clearItemOcrImage();form.dataset.itemOcr='false';form.querySelector('[type="submit"]').textContent='Guardar';}else if(form.dataset.itemOcrReview==='true'){clearItemOcrImage();form.dataset.itemOcrReview='false';document.querySelector('#itemOcrEditorPreview')?.remove();form.querySelector('[type="submit"]').textContent='Guardar';}});
